/** Candidate contract. No network, authentication or platform integration. */
export function canonical(value) {
 if(value===null||typeof value==='boolean'||typeof value==='string')return JSON.stringify(value);
 if(typeof value==='number'&&Number.isFinite(value))return JSON.stringify(value);
 if(Array.isArray(value))return '['+value.map(canonical).join(',')+']';
 if(value&&Object.getPrototypeOf(value)===Object.prototype)return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+canonical(value[k])).join(',')+'}';
 throw new Error('non-JSON contract value');
}
export async function digest(value) {const bytes=value instanceof Uint8Array?value:new TextEncoder().encode(canonical(value));return [...new Uint8Array(await globalThis.crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');}
const id=v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{1,96}$/.test(v);
const sha=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v);
function keys(obj,allowed){if(!obj||Object.getPrototypeOf(obj)!==Object.prototype||Object.keys(obj).some(k=>!allowed.includes(k)))throw new Error('unknown contract field');}
export async function styleProfile(input) {
 keys(input,['styleFamilyId','profileId','version','compatProfile']);
 if(!id(input.styleFamilyId)||!id(input.profileId)||!Number.isInteger(input.version)||input.version<1)throw new Error('invalid style profile identity');
 const c=input.compatProfile;keys(c,['pixelScale','density','paletteId','palette','projection','lighting']);
 for(const [k,unit] of [['pixelScale','source-px/game-px'],['density','source-px/world-unit']]){keys(c[k],['value','unit']);if(typeof c[k].value!=='number'||!Number.isFinite(c[k].value)||c[k].value<=0||c[k].unit!==unit)throw new Error('unknown or invalid compatibility scale');}
 if(!id(c.paletteId)||!id(c.projection)||!id(c.lighting)||[c.paletteId,c.projection,c.lighting].includes('unknown')||(c.palette!==undefined&&(!Array.isArray(c.palette)||!c.palette.length||c.palette.length>256||c.palette.some(v=>!/^#[a-fA-F0-9]{6}$/.test(v)))))throw new Error('unknown or invalid compatibility profile');
 const profile=JSON.parse(canonical(input));return {...profile,hash:await digest(profile.compatProfile)};
}
export async function verifyProfile(profile){const {hash,...fields}=profile;const checked=await styleProfile(fields);if(hash!==checked.hash)throw new Error('style profile hash mismatch');return checked;}
export function semanticItem(item){keys(item,['itemId','category','orientations']);if(!id(item.itemId)||!id(item.category)||!Array.isArray(item.orientations)||!item.orientations.length||item.orientations.some(o=>!id(o))||new Set(item.orientations).size!==item.orientations.length)throw new Error('invalid semantic item');return JSON.parse(canonical(item));}
export function rendition(input){keys(input,['renditionId','assetId','revision','hash','itemId','category','orientation','styleFamilyId','profileId','profileVersion','profileHash','status','bytes','mime','eligibility']);if(!['renditionId','assetId','itemId','category','orientation','styleFamilyId','profileId'].every(k=>id(input[k]))||!Number.isInteger(input.revision)||input.revision<1||!Number.isInteger(input.profileVersion)||input.profileVersion<1||!sha(input.hash)||!sha(input.profileHash)||!['published','candidate'].includes(input.status)||!Number.isInteger(input.bytes)||input.bytes<1||input.bytes>5*1024**2||!['image/png','image/webp'].includes(input.mime))throw new Error('invalid rendition');if(input.eligibility!==undefined){keys(input.eligibility,['licenseAllowed','qualityApproved','approvalHash']);if(typeof input.eligibility.licenseAllowed!=='boolean'||typeof input.eligibility.qualityApproved!=='boolean'||(input.eligibility.approvalHash!==null&&!sha(input.eligibility.approvalHash)))throw new Error('invalid rendition eligibility');}return JSON.parse(canonical(input));}
export function queryRenditions(catalog,profile,filter={}){keys(filter,['itemId','category','orientation']);if(Object.values(filter).some(v=>!id(v)))throw new Error('invalid query');return catalog.map(rendition).filter(r=>r.status==='published'&&r.eligibility?.licenseAllowed===true&&r.eligibility?.qualityApproved===true&&r.eligibility.approvalHash===r.hash&&r.styleFamilyId===profile.styleFamilyId&&r.profileId===profile.profileId&&r.profileVersion===profile.version&&r.profileHash===profile.hash&&Object.entries(filter).every(([k,v])=>r[k]===v));}
export function semanticLayout(layout){keys(layout,['width','height','placements']);if(!Number.isInteger(layout.width)||!Number.isInteger(layout.height)||layout.width<1||layout.height<1||layout.width>256||layout.height>256||!Array.isArray(layout.placements)||layout.placements.length>128)throw new Error('invalid layout');for(const p of layout.placements){keys(p,['slotId','itemId','orientation','x','y']);if(!id(p.slotId)||!id(p.itemId)||!id(p.orientation)||!Number.isInteger(p.x)||!Number.isInteger(p.y)||p.x<0||p.y<0||p.x>=layout.width||p.y>=layout.height)throw new Error('invalid semantic placement');}if(new Set(layout.placements.map(p=>p.slotId)).size!==layout.placements.length)throw new Error('duplicate slot');return JSON.parse(canonical(layout));}
export async function roomManifest({roomId,profile,layout,catalog,pins}) {
 if(!id(roomId))throw new Error('invalid room ID');const checked=await verifyProfile(profile),clean=semanticLayout(layout),assets=[];
 if(pins!==undefined&&(!Array.isArray(pins)||pins.length!==clean.placements.length||new Set(pins.map(p=>p.slotId)).size!==pins.length))throw new Error('exact placement pins required');
 for(const p of clean.placements){let matches=queryRenditions(catalog,checked,{itemId:p.itemId,orientation:p.orientation});if(pins){const pin=pins.find(a=>a.slotId===p.slotId);if(!pin)throw new Error('placement pin missing');matches=matches.filter(r=>r.renditionId===pin.renditionId&&r.assetId===pin.assetId&&r.revision===pin.revision&&r.hash===pin.hash);}if(matches.length!==1)throw new Error('unique compatible rendition required');const r=matches[0];assets.push({slotId:p.slotId,renditionId:r.renditionId,assetId:r.assetId,revision:r.revision,hash:r.hash,bytes:r.bytes,mime:r.mime});}
 const body={schemaVersion:1,roomId,profile:checked,layout:clean,assets};return {...body,hash:await digest(body)};
}
export async function verifyRoom(room,catalog){keys(room,['schemaVersion','roomId','profile','layout','assets','hash']);if(room.schemaVersion!==1)throw new Error('room schema unsupported');const rebuilt=await roomManifest({roomId:room.roomId,profile:room.profile,layout:room.layout,catalog,pins:room.assets});if(canonical(rebuilt)!==canonical(room))throw new Error('room lock mismatch');return rebuilt;}
/** Inject trusted readonlyLoad(rendition lock), never URLs. cacheStore: get/set/delete/keys. */
export class RuntimeResolver {
 constructor({catalog,readonlyLoad,cacheStore,maxCacheBytes=16*1024**2,loadTimeoutMs=5000}){if(!Number.isInteger(loadTimeoutMs)||loadTimeoutMs<1||loadTimeoutMs>15000)throw new Error('invalid load timeout');this.timeout=loadTimeoutMs;this.catalog=catalog.map(rendition);this.load=readonlyLoad;this.cache=cacheStore;this.limit=maxCacheBytes;if(!Number.isInteger(maxCacheBytes)||maxCacheBytes<0)throw new Error('invalid cache budget');}
 async cached(lock){if(!this.cache)return null;const bytes=await this.cache.get(lock.hash);if(!bytes)return null;if(!(bytes instanceof Uint8Array)||bytes.length!==lock.bytes||await digest(bytes)!==lock.hash){await this.cache.delete(lock.hash);return null;}return new Uint8Array(bytes);}
 async store(lock,bytes){if(!this.cache||bytes.length>this.limit)return;let usage=0;const entries=[];for(const key of await this.cache.keys()){const b=await this.cache.get(key);if(!(b instanceof Uint8Array)||!sha(key)){await this.cache.delete(key);continue;}usage+=b.length;entries.push({key,size:b.length});}for(const e of entries){if(usage+bytes.length<=this.limit)break;await this.cache.delete(e.key);usage-=e.size;}if(usage+bytes.length<=this.limit)await this.cache.set(lock.hash,new Uint8Array(bytes));}
 async boundedLoad(lock){const controller=new AbortController();let timer;const deadline=new Promise((_,reject)=>{timer=setTimeout(()=>{controller.abort();reject(new Error('locked asset load timed out'));},this.timeout);});try{return await Promise.race([Promise.resolve().then(()=>this.load(Object.freeze({...lock}),{signal:controller.signal})),deadline]);}finally{clearTimeout(timer);}}
 async resolve(room){const checked=await verifyRoom(room,this.catalog),files=[];for(const lock of checked.assets){let bytes=await this.cached(lock);if(!bytes){if(typeof this.load!=='function')throw new Error('locked asset unavailable');bytes=await this.boundedLoad(lock);if(!(bytes instanceof Uint8Array)||bytes.length!==lock.bytes||await digest(bytes)!==lock.hash)throw new Error('loaded asset integrity failure');await this.store(lock,bytes);}files.push({slotId:lock.slotId,bytes:new Uint8Array(bytes)});}return {room:checked,files,mode:'requested'};}
 async resolveWithFallback(room,{template,packagedFiles}){try{return await this.resolve(room);}catch(error){const requestedProfile=await verifyProfile(room.profile);const templateProfile=await verifyProfile(template.profile);if(canonical(requestedProfile)!==canonical(templateProfile))throw new Error('offline template profile mismatch');const checkedTemplate=await verifyRoom(template,this.catalog);const files=[];for(const lock of checkedTemplate.assets){const bytes=packagedFiles.get(lock.hash);if(!(bytes instanceof Uint8Array)||bytes.length!==lock.bytes||await digest(bytes)!==lock.hash)throw new Error('offline template integrity failure');files.push({slotId:lock.slotId,bytes:new Uint8Array(bytes)});}return {room:checkedTemplate,files,mode:'offline-template',reason:'requested-room-unavailable'};}}
}
/** Explicit metadata adapter: copies only known fields; never interprets source URLs. */
export function metadataRendition(metadata){return rendition({renditionId:metadata.renditionId,assetId:metadata.assetId,revision:metadata.revision,hash:metadata.hash,itemId:metadata.semanticItemId,category:metadata.category,orientation:metadata.orientation,styleFamilyId:metadata.styleFamilyId,profileId:metadata.profileId,profileVersion:metadata.profileVersion,profileHash:metadata.profileHash,status:metadata.status,bytes:metadata.bytes,mime:metadata.mime,eligibility:{licenseAllowed:metadata.license?.allowed===true&&id(metadata.license?.id)&&metadata.license.id!=='unknown'&&typeof metadata.license?.name==='string'&&!!metadata.license.name.trim()&&typeof metadata.license?.notice==='string'&&!!metadata.license.notice.trim()&&typeof metadata.source?.url==='string'&&!!metadata.source.url.trim()&&metadata.rights?.status==='documented',qualityApproved:metadata.approval?.hash===metadata.hash&&sha(metadata.approval?.manifestHash)&&typeof metadata.approval?.actor==='string'&&!!metadata.approval.actor&&typeof metadata.approval?.at==='string'&&!!metadata.approval.at,approvalHash:metadata.approval?.hash??null}});}
